// 현재 시간 타임스탬프 및 ISO 문자열
const now = new Date();
return `Timestamp (ms): ${now.getTime()}
Timestamp (s):  ${Math.floor(now.getTime() / 1000)}
ISO 8601:       ${now.toISOString()}
Local (KST):     ${now.toLocaleString()}`;

// 무작위 HEX 토큰 생성 (파라미터 지원: params.bytes)
const numBytes = (typeof params !== 'undefined' && params && params.bytes) ? Math.max(1, parseInt(params.bytes, 10)) : 16;
const bytes = new Uint8Array(numBytes);
if (window.crypto && crypto.getRandomValues) {
    crypto.getRandomValues(bytes);
} else {
    for (let i = 0; i < numBytes; i++) bytes[i] = Math.floor(Math.random() * 256);
}
return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
